# Create API client wrapper for Hugging Face
api_client_content = '''#!/usr/bin/env python3
"""
The New Civilization - Hugging Face API Client
Ultra-Lightweight API Wrapper for Hugging Face Services
"""

import json
import time
import requests
from typing import Dict, List, Optional, Any
from datetime import datetime

class HuggingFaceClient:
    """Ultra-lightweight Hugging Face API client"""

    def __init__(self, token: str, base_url: str = "https://api-inference.huggingface.co/models"):
        self.token = token
        self.base_url = base_url
        self.session = requests.Session()
        self.session.headers.update({
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json"
        })

        # Statistics tracking
        self.stats = {
            "requests_made": 0,
            "successful_requests": 0,
            "failed_requests": 0,
            "total_response_time": 0,
            "revenue_generated": 0.0
        }

    def _make_request(self, model: str, payload: dict, timeout: int = 60) -> Dict[str, Any]:
        """Make request to HF API with error handling and stats tracking"""
        url = f"{self.base_url}/{model}"

        start_time = time.time()
        self.stats["requests_made"] += 1

        try:
            response = self.session.post(url, json=payload, timeout=timeout)
            response_time = time.time() - start_time
            self.stats["total_response_time"] += response_time

            if response.status_code == 200:
                self.stats["successful_requests"] += 1
                return {
                    "success": True,
                    "data": response.json(),
                    "response_time": response_time,
                    "status_code": response.status_code
                }
            elif response.status_code == 503:
                # Model is loading, return appropriate message
                return {
                    "success": False,
                    "error": "Model is currently loading, please retry in a few seconds",
                    "status_code": response.status_code,
                    "retry_after": 20
                }
            else:
                self.stats["failed_requests"] += 1
                return {
                    "success": False,
                    "error": f"HTTP {response.status_code}: {response.text}",
                    "status_code": response.status_code
                }

        except requests.exceptions.Timeout:
            self.stats["failed_requests"] += 1
            return {
                "success": False,
                "error": "Request timeout",
                "status_code": 408
            }
        except requests.exceptions.ConnectionError:
            self.stats["failed_requests"] += 1
            return {
                "success": False,
                "error": "Connection error",
                "status_code": 0
            }
        except Exception as e:
            self.stats["failed_requests"] += 1
            return {
                "success": False,
                "error": str(e),
                "status_code": 500
            }

    def text_generation(self, model: str, prompt: str, max_length: int = 100, 
                       temperature: float = 0.7, top_p: float = 0.9) -> Dict[str, Any]:
        """Generate text using specified model"""
        payload = {
            "inputs": prompt,
            "parameters": {
                "max_length": max_length,
                "temperature": temperature,
                "top_p": top_p,
                "return_full_text": False
            }
        }
        return self._make_request(model, payload)

    def sentiment_analysis(self, model: str, text: str) -> Dict[str, Any]:
        """Analyze sentiment of text"""
        payload = {"inputs": text}
        return self._make_request(model, payload)

    def summarization(self, model: str, text: str, max_length: int = 150, 
                     min_length: int = 50) -> Dict[str, Any]:
        """Summarize text using specified model"""
        payload = {
            "inputs": text,
            "parameters": {
                "max_length": max_length,
                "min_length": min_length,
                "do_sample": False
            }
        }
        return self._make_request(model, payload)

    def translation(self, model: str, text: str) -> Dict[str, Any]:
        """Translate text using specified model"""
        payload = {"inputs": text}
        return self._make_request(model, payload)

    def question_answering(self, model: str, question: str, context: str) -> Dict[str, Any]:
        """Answer question based on context"""
        payload = {
            "inputs": {
                "question": question,
                "context": context
            }
        }
        return self._make_request(model, payload)

    def text_classification(self, model: str, text: str) -> Dict[str, Any]:
        """Classify text using specified model"""
        payload = {"inputs": text}
        return self._make_request(model, payload)

    def feature_extraction(self, model: str, text: str) -> Dict[str, Any]:
        """Extract features/embeddings from text"""
        payload = {"inputs": text}
        return self._make_request(model, payload)

    def conversational(self, model: str, text: str, conversation_id: Optional[str] = None) -> Dict[str, Any]:
        """Generate conversational response"""
        payload = {
            "inputs": {
                "text": text,
                "conversation_id": conversation_id
            }
        }
        return self._make_request(model, payload)

    def batch_process(self, requests_data: List[Dict[str, Any]], delay: float = 1.0) -> List[Dict[str, Any]]:
        """Process multiple requests with rate limiting"""
        results = []

        for i, request_data in enumerate(requests_data):
            method = request_data.get("method")
            model = request_data.get("model")
            params = request_data.get("parameters", {})

            # Route to appropriate method
            if method == "text_generation":
                result = self.text_generation(model, **params)
            elif method == "sentiment_analysis":
                result = self.sentiment_analysis(model, **params)
            elif method == "summarization":
                result = self.summarization(model, **params)
            elif method == "translation":
                result = self.translation(model, **params)
            elif method == "question_answering":
                result = self.question_answering(model, **params)
            elif method == "text_classification":
                result = self.text_classification(model, **params)
            else:
                result = {"success": False, "error": f"Unknown method: {method}"}

            result["request_id"] = i
            results.append(result)

            # Rate limiting delay (except for last request)
            if i < len(requests_data) - 1:
                time.sleep(delay)

        return results

    def get_statistics(self) -> Dict[str, Any]:
        """Get client usage statistics"""
        total_requests = self.stats["requests_made"]
        if total_requests > 0:
            success_rate = (self.stats["successful_requests"] / total_requests) * 100
            avg_response_time = self.stats["total_response_time"] / total_requests
        else:
            success_rate = 0
            avg_response_time = 0

        return {
            "total_requests": total_requests,
            "successful_requests": self.stats["successful_requests"],
            "failed_requests": self.stats["failed_requests"],
            "success_rate_percent": success_rate,
            "average_response_time_seconds": avg_response_time,
            "total_response_time": self.stats["total_response_time"],
            "revenue_generated": self.stats["revenue_generated"]
        }

    def health_check(self) -> Dict[str, Any]:
        """Check API health with a simple request"""
        test_model = "microsoft/DialoGPT-medium"
        test_payload = {"inputs": "Hello"}

        result = self._make_request(test_model, test_payload)

        return {
            "api_accessible": result["success"],
            "response_time": result.get("response_time", 0),
            "status": "healthy" if result["success"] else "unhealthy",
            "error": result.get("error") if not result["success"] else None
        }

# Example usage and testing
if __name__ == "__main__":
    # Initialize client (replace with your token)
    client = HuggingFaceClient("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")

    print("🤖 The New Civilization - HF API Client Test")
    print("=" * 50)

    # Health check
    health = client.health_check()
    print(f"🏥 Health Check: {health['status']}")

    if health["api_accessible"]:
        # Test text generation
        print("\\n📝 Testing Text Generation...")
        result = client.text_generation(
            "microsoft/DialoGPT-medium",
            "The future of artificial intelligence is",
            max_length=50
        )

        if result["success"]:
            print(f"✅ Success: {result['data']}")
        else:
            print(f"❌ Failed: {result['error']}")

        # Show statistics
        print("\\n📊 Statistics:")
        stats = client.get_statistics()
        for key, value in stats.items():
            print(f"   {key}: {value}")
    else:
        print(f"❌ API not accessible: {health['error']}")
'''

# Write api_client.py
